module keypad_scanner #( parameter integer CLK_HZ = 20_000_000, parameter integer SCAN_HZ = 1000 ) ( input logic clk, input logic reset,
// Keypad interface
// Columns are driven active-low.
output logic [3:0] col,

// Rows are read active-low.
input  logic [3:0] row,

// Key status and decoded key
output logic       key_pressed,
output logic [3:0] key_code
);
//----------------------------------------------------------------------
// Clock divider
//
// Generates a scan tick at approximately SCAN_HZ.
//----------------------------------------------------------------------
localparam integer DIVIDER =
    (CLK_HZ / SCAN_HZ);

localparam integer DIV_WIDTH =
    (DIVIDER &lt;= 2) ? 1 : $clog2(DIVIDER);

logic [DIV_WIDTH-1:0] div_count;
logic                 scan_tick;

always_ff @(posedge clk) begin
    if (reset) begin
        div_count &lt;= '0;
        scan_tick &lt;= 1'b0;
    end
    else begin
        scan_tick &lt;= 1'b0;

        if (div_count == DIVIDER - 1) begin
            div_count &lt;= '0;
            scan_tick &lt;= 1'b1;
        end
        else begin
            div_count &lt;= div_count + 1'b1;
        end
    end
end

//----------------------------------------------------------------------
// Scanner FSM
//
// DRIVE state:
//   Select one column.
//
// SAMPLE state:
//   Read the rows after the column has been driven for one scan tick.
//
// HOLD state:
//   A key has been detected. Continue scanning, but do not register
//   another key until all rows are released.
//----------------------------------------------------------------------
typedef enum logic [1:0] {
    ST_DRIVE,
    ST_SAMPLE,
    ST_HOLD
} state_t;

state_t state;

logic [1:0] column_index;

//----------------------------------------------------------------------
// Temporary debounce/confirmation information.
//
// A candidate must be observed on two consecutive complete scans before
// key_pressed is asserted. This provides basic debounce protection.
//----------------------------------------------------------------------
logic       candidate_valid;
logic [3:0] candidate_code;

logic [3:0] sampled_code;
logic       sampled_valid;

//----------------------------------------------------------------------
// Decode the currently selected column and active-low row inputs.
//
// Only the first active row is used. This intentionally treats the
// keypad as a single-key-at-a-time interface.
//----------------------------------------------------------------------
always_comb begin
    sampled_valid = 1'b0;
    sampled_code  = 4'h0;

    case (column_index)

        2'd0: begin
            if (!row[0]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h1;
            end
            else if (!row[1]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h4;
            end
            else if (!row[2]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h7;
            end
            else if (!row[3]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hE;   // *
            end
        end

        2'd1: begin
            if (!row[0]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h2;
            end
            else if (!row[1]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h5;
            end
            else if (!row[2]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h8;
            end
            else if (!row[3]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h0;
            end
        end

        2'd2: begin
            if (!row[0]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h3;
            end
            else if (!row[1]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h6;
            end
            else if (!row[2]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'h9;
            end
            else if (!row[3]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hF;   // #
            end
        end

        2'd3: begin
            if (!row[0]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hA;
            end
            else if (!row[1]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hB;
            end
            else if (!row[2]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hC;
            end
            else if (!row[3]) begin
                sampled_valid = 1'b1;
                sampled_code  = 4'hD;
            end
        end

        default: begin
            sampled_valid = 1'b0;
            sampled_code  = 4'h0;
        end

    endcase
end

//----------------------------------------------------------------------
// Column driver
//
// Exactly one column is asserted low.
//----------------------------------------------------------------------
always_comb begin
    case (column_index)
        2'd0: col = 4'b1110;
        2'd1: col = 4'b1101;
        2'd2: col = 4'b1011;
        2'd3: col = 4'b0111;

        default: col = 4'b1111;
    endcase
end

//----------------------------------------------------------------------
// Main scanner FSM
//----------------------------------------------------------------------
always_ff @(posedge clk) begin
    if (reset) begin
        state          &lt;= ST_DRIVE;
        column_index   &lt;= 2'd0;

        candidate_valid &lt;= 1'b0;
        candidate_code  &lt;= 4'h0;

        key_pressed     &lt;= 1'b0;
        key_code        &lt;= 4'h0;
    end
    else if (scan_tick) begin

        case (state)

            //----------------------------------------------------------
            // Drive a column, then wait for the next scan tick.
            //----------------------------------------------------------
            ST_DRIVE: begin
                state &lt;= ST_SAMPLE;
            end

            //----------------------------------------------------------
            // Sample the rows for the currently active column.
            //----------------------------------------------------------
            ST_SAMPLE: begin

                if (sampled_valid) begin

                    // First observation of a key.
                    if (!candidate_valid) begin
                        candidate_valid &lt;= 1'b1;
                        candidate_code  &lt;= sampled_code;
                    end

                    // Same key observed again: accept it.
                    else if (candidate_code == sampled_code) begin
                        key_pressed &lt;= 1'b1;
                        key_code    &lt;= sampled_code;

                        state &lt;= ST_HOLD;
                    end

                    // Different key: restart debounce.
                    else begin
                        candidate_valid &lt;= 1'b1;
                        candidate_code  &lt;= sampled_code;
                    end

                end
                else begin
                    // No key in this column.
                    //
                    // Continue scanning the remaining columns.
                    candidate_valid &lt;= 1'b0;

                    if (column_index == 2'd3) begin
                        column_index &lt;= 2'd0;
                    end
                    else begin
                        column_index &lt;= column_index + 1'b1;
                    end
                end

                // If the current column produced a key, remain on it
                // for confirmation on the next scan tick.
                if (sampled_valid) begin
                    state &lt;= ST_SAMPLE;
                end
                else begin
                    state &lt;= ST_DRIVE;
                end
            end

            //----------------------------------------------------------
            // A key is being held.
            //
            // Do not accept another key until the keypad is completely
            // released.
            //----------------------------------------------------------
            ST_HOLD: begin

                if (!sampled_valid) begin
                    // This column is released. Continue through the
                    // remaining columns to make sure no other key is
                    // still pressed.
                    if (column_index == 2'd3) begin
                        key_pressed    &lt;= 1'b0;
                        candidate_valid &lt;= 1'b0;
                        column_index   &lt;= 2'd0;
                        state          &lt;= ST_DRIVE;
                    end
                    else begin
                        column_index &lt;= column_index + 1'b1;
                        state        &lt;= ST_DRIVE;
                    end
                end
                else begin
                    // Key is still being held.
                    state &lt;= ST_HOLD;
                end
            end

            default: begin
                state &lt;= ST_DRIVE;
            end

        endcase
    end
end
endmodule



